import fs from "node:fs/promises";
import path from "node:path";
import mime from "mime-types";
import { NextRequest, NextResponse } from "next/server";
import { SettingsService } from "@/app/services/settings-service";

const settingsService = new SettingsService();

export async function GET(request: NextRequest) {
    const relativePath = request.nextUrl.searchParams.get("path");

    if (!relativePath) {
        return NextResponse.json({ error: "path is required" }, { status: 400 });
    }

    try {
        const outputDirectory = settingsService.getComfyOutputDirectory();
        const normalizedPath = path.normalize(relativePath).replace(/^([/\\])+/, "");
        const absolutePath = path.resolve(outputDirectory, normalizedPath);
        const relativeToOutput = path.relative(outputDirectory, absolutePath);

        if (relativeToOutput.startsWith("..") || path.isAbsolute(relativeToOutput)) {
            return NextResponse.json({ error: "invalid path" }, { status: 400 });
        }

        const fileBuffer = await fs.readFile(absolutePath);
        const contentType = mime.lookup(absolutePath) || "application/octet-stream";

        return new NextResponse(fileBuffer, {
            headers: {
                "Content-Type": contentType,
                "Cache-Control": "public, max-age=3600",
            },
        });
    } catch (error) {
        const message = error instanceof Error ? error.message : "Unknown file error";
        return NextResponse.json({ error: message }, { status: 404 });
    }
}